"""Literal device AST ownership/order interpreter with an independent sum tree.

The reference tree transcribes the fingerprinted ATen thread_reduce_impl and
block_y_reduce. Tests also mutate the emitted AST to make each obligation fail.
"""

from __future__ import annotations

import ast
from collections import Counter
from dataclasses import asdict
from dataclasses import dataclass
from dataclasses import field
from pathlib import Path
from types import SimpleNamespace
from typing import TYPE_CHECKING

from helion._compiler.cute import paired_sum_runtime
from helion._compiler.cute import single_sum_runtime

if TYPE_CHECKING:
    from helion.runtime.cute.paired_sum import SumPlan


@dataclass(frozen=True, slots=True)
class Value:
    op: str
    args: tuple[object, ...] = ()

    def __add__(self, other: Value) -> Value:
        assert isinstance(other, Value)
        if self == ZERO and other == ZERO:
            return ZERO
        return Value("add_rn_f32", (self, other))


ZERO = Value("positive_zero")


def float32(value: object) -> Value:
    if isinstance(value, Value):
        return value
    assert value == 0
    return ZERO


def cast_bf16(value: Value) -> Value:
    return Value("cast_bfloat16", (value,))


def cast_fp16(value: Value) -> Value:
    return Value("cast_float16", (value,))


class Register:
    def __init__(self, shape: int | tuple[int, ...], dtype: object) -> None:
        self.shape = (shape,) if isinstance(shape, int) else shape
        self.element_type = dtype
        self.values = {}

    def _key(self, key: int | tuple[int, ...]) -> tuple[int, ...]:
        key = (key,) if isinstance(key, int) else key
        assert len(key) == len(self.shape)
        assert all(
            0 <= index < size for index, size in zip(key, self.shape, strict=True)
        )
        return key

    def __getitem__(self, key: int | tuple[int, ...]) -> Value:
        return self.values[self._key(key)]

    def __setitem__(self, key: int | tuple[int, ...], value: Value) -> None:
        assert isinstance(value, Value)
        self.values[self._key(key)] = value

    def fill(self, value: Value) -> None:
        import itertools

        for key in itertools.product(*(range(size) for size in self.shape)):
            self.values[key] = value


class Global:
    def __init__(
        self,
        kind: str,
        stream: int,
        rows: int,
        columns: int,
        stride: int,
        output_type: object = cast_bf16,
    ) -> None:
        self.kind = kind
        self.stream = stream
        self.rows = rows
        self.columns = columns
        self.layout = SimpleNamespace(stride=(stride, 1))
        self.element_type = float32 if kind == "input" else output_type
        self.loads = Counter()
        self.stores = {}

    def load(self, offset: int) -> Value:
        assert self.kind == "input"
        row, column = divmod(offset, self.layout.stride[0])
        assert 0 <= row < self.rows and 0 <= column < self.columns, (row, column)
        self.loads[row, column] += 1
        return Value("input", (self.stream, row, column))

    def store(self, offset: int, value: Value) -> None:
        assert self.kind == "output" and 0 <= offset < self.columns
        assert offset not in self.stores, (self.stream, offset)
        self.stores[offset] = value


@dataclass
class Shared:
    size: int
    values: dict[int, Value] = field(default_factory=dict)
    writes: Counter = field(default_factory=Counter)

    element_type = float32

    def load(self, offset: int) -> Value:
        assert 0 <= offset < self.size
        assert offset in self.values, ("shared read before publication", offset)
        return self.values[offset]

    def store(self, offset: int, value: Value) -> None:
        assert 0 <= offset < self.size
        self.values[offset] = value
        self.writes[offset] += 1


def load_vector(tensor: object, offset: int, width: int) -> Register:
    assert offset % width == 0
    value = Register(width, tensor.element_type)
    for lane in range(width):
        value[lane] = tensor.load(offset + lane)
    return value


def store_vector(tensor: object, offset: int, fragment: Register, width: int) -> None:
    assert offset % width == 0
    for lane in range(width):
        tensor.store(offset + lane, fragment[lane])


def literal_kernel_ast(single: bool = False) -> ast.FunctionDef:
    module = single_sum_runtime if single else paired_sum_runtime
    name = "single_sum_cast_kernel" if single else "paired_sum_cast_kernel"
    tree = ast.parse(Path(module.__file__).read_text())
    return next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name == name
    )


class InterpreterTransform(ast.NodeTransformer):
    def visit_Expr(self, node: ast.Expr) -> object:
        if (
            isinstance(node.value, ast.Call)
            and ast.unparse(node.value.func) == "cute.arch.sync_threads"
        ):
            return ast.Expr(value=ast.Yield(value=ast.Constant("cta_barrier")))
        return self.generic_visit(node)


def run_literal(
    plan: SumPlan,
    *,
    stride: int | None = None,
    mutation: str | None = None,
    return_expressions: bool = False,
    single: bool = False,
    output_dtype: str = "bfloat16",
) -> dict[str, object]:
    output_type = {
        "bfloat16": cast_bf16,
        "float16": cast_fp16,
        "float32": float32,
    }[output_dtype]
    streams = 1 if single else 2
    stride = plan.columns if stride is None else stride
    if plan.columns == 0:
        assert plan.grid[0] == 0
        return {"plan": asdict(plan), "loads": 0, "stores": 0, "barriers": 0}
    inputs = [
        Global("input", stream, plan.rows, plan.columns, stride)
        for stream in range(streams)
    ]
    outputs = [
        Global("output", stream, 1, plan.columns, plan.columns, output_type)
        for stream in range(streams)
    ]
    node = literal_kernel_ast(single)
    node.decorator_list = []
    for arg in node.args.args:
        arg.annotation = None
    # These are explicit negative controls against the literal emitted code.
    text = ast.unparse(node)
    if mutation == "missing_barrier":
        text = text.replace("cute.arch.sync_threads()", "pass")
    elif mutation == "ascending_tree":
        text = text.replace("row_lanes >> level + 1", "1 << level")
    elif mutation == "missing_row_guard":
        text = text.replace("row < rows and column < columns", "column < columns")
    elif mutation == "missing_column_guard":
        text = text.replace("row < rows and column < columns", "row < rows")
    elif mutation == "cast_partial":
        text = text.replace(
            "+ values_left[lane]", "+ cutlass.BFloat16(values_left[lane])"
        )
    elif mutation == "reuse_left_output":
        text = text.replace(
            "right_out, column, final_right", "left_out, column, final_right"
        )
    elif mutation == "wrong_source":
        text = text.replace(
            "_cute_resident_load_vector(right,", "_cute_resident_load_vector(left,"
        )
    elif mutation is not None:
        raise AssertionError(mutation)
    if mutation:
        assert text != ast.unparse(node), mutation
    node = ast.parse(text).body[0]
    node = InterpreterTransform().visit(node)
    # Force a generator also for plans with no barrier or the negative control.
    node.body.append(
        ast.If(
            test=ast.Constant(False),
            body=[ast.Expr(value=ast.Yield(value=ast.Constant(None)))],
            orelse=[],
        )
    )
    module = ast.fix_missing_locations(ast.Module(body=[node], type_ignores=[]))
    context = {"tid": (0, 0, 0), "bid": (0, 0, 0), "shared": None}

    def allocate(dtype: object, size: int, alignment: int) -> Shared:
        assert dtype is float32 and alignment == 16
        if context["shared"] is None:
            context["shared"] = Shared(size)
        assert context["shared"].size == size
        return context["shared"]

    cute = SimpleNamespace(
        arch=SimpleNamespace(
            block_idx=lambda: context["bid"],
            thread_idx=lambda: context["tid"],
            alloc_smem=allocate,
        ),
        make_rmem_tensor=Register,
        make_tensor=lambda pointer, layout: pointer,
        make_layout=lambda shape: shape,
        ceil_div=lambda a, b: (a + b - 1) // b,
    )
    cutlass = SimpleNamespace(
        Int32=int,
        Float32=float32,
        BFloat16=cast_bf16,
        Constexpr=object,
        range_constexpr=range,
        const_expr=bool,
    )
    scope = {
        "cute": cute,
        "cutlass": cutlass,
        "_cute_resident_load_vector": load_vector,
        "_cute_resident_store_vector": store_vector,
    }
    exec(compile(module, "<literal paired tail interpreter>", "exec"), scope)
    kernel = scope[node.name]
    barriers = 0
    shared_bytes = 0
    for block in range(plan.grid[0]):
        context["bid"] = (block, 0, 0)
        context["shared"] = None
        threads = [
            (
                (tx, ty, 0),
                kernel(
                    *inputs,
                    *outputs,
                    plan.rows,
                    plan.columns,
                    plan.row_lanes,
                    plan.column_threads,
                    plan.vector,
                ),
            )
            for ty in range(plan.row_lanes)
            for tx in range(plan.column_threads)
        ]
        while threads:
            live = []
            for tid, thread in threads:
                context["tid"] = tid
                try:
                    assert next(thread) == "cta_barrier"
                    live.append((tid, thread))
                except StopIteration:
                    pass
            assert len(live) in (0, len(threads)), "divergent CTA barrier"
            if live:
                barriers += 1
            threads = live
        if context["shared"] is not None:
            shared_bytes = max(shared_bytes, context["shared"].size * 4)
    for stream, tensor in enumerate(inputs):
        assert len(tensor.loads) == plan.rows * plan.columns
        assert all(value == 1 for value in tensor.loads.values())
        out = outputs[stream]
        assert set(out.stores) == set(range(plan.columns))
        for column, value in out.stores.items():
            assert value == output_type(
                reference_tree(plan.rows, plan.row_lanes, stream, column)
            ), (stream, column, mutation)
    result = {
        "plan": asdict(plan),
        "stride": stride,
        "loads": sum(sum(t.loads.values()) for t in inputs),
        "stores": sum(len(t.stores) for t in outputs),
        "barriers": barriers,
        "shared_bytes": shared_bytes,
        "reference_tree_equal_per_output": True,
        "single_final_cast": True,
        "each_input_loaded_once": True,
        "every_output_written_once": True,
    }
    if return_expressions:
        result["expressions"] = [tensor.stores for tensor in outputs]
    return result


def reference_tree(rows: int, row_lanes: int, stream: int, column: int) -> Value:
    """Independent Reduce.cuh thread_reduce_impl + block_y_reduce transcription."""
    thread_values = []
    for ty in range(row_lanes):
        idx = ty
        stride = row_lanes
        values = [ZERO] * 4
        while idx + 3 * stride < rows:
            for slot in range(4):
                values[slot] = values[slot] + Value(
                    "input", (stream, idx + slot * stride, column)
                )
            idx += 4 * stride
        for slot in range(4):
            if idx >= rows:
                break
            values[slot] = values[slot] + Value("input", (stream, idx, column))
            idx += stride
        result = values[0]
        for slot in range(1, 4):
            result = result + values[slot]
        thread_values.append(result)
    offset = row_lanes // 2
    while offset:
        for ty in range(offset):
            thread_values[ty] = thread_values[ty] + thread_values[ty + offset]
        offset //= 2
    return thread_values[0]

"""Integer range admission before materialization enables native half/BF16 MMA."""

from __future__ import annotations

from typing import TYPE_CHECKING
from unittest.mock import patch

import pytest
import torch
from torch.fx import Graph
from torch.fx import Node

from test.test_cute_fuse_mm_accumulation import _cpu_target
from test.test_cute_signed_bitfield_bf16 import _graph

import helion
from helion._compiler.cute.materialize_operand import _exact_integer_cast
from helion._compiler.cute.tcgen05_config import CuteTcgen05Config
from helion._testing import skipUnlessBackends
import helion.language as hl

if TYPE_CHECKING:
    from torch._ops import OpOverload


def _cast(
    source_dtype: torch.dtype,
    destination_dtype: torch.dtype,
    target: OpOverload,
) -> Node:
    graph = Graph()
    source = graph.placeholder("source")
    # Even an all-zero sample is not proof of the runtime integer range.
    source.meta["val"] = torch.zeros((2, 8), dtype=source_dtype)
    if target is torch.ops.prims.convert_element_type.default:
        value = graph.call_function(target, (source, destination_dtype))
    else:
        value = graph.call_function(target, (source,), {"dtype": destination_dtype})
    value.meta["val"] = torch.empty((2, 8), dtype=destination_dtype)
    return value


@pytest.mark.parametrize(
    "target",
    (torch.ops.aten._to_copy.default, torch.ops.prims.convert_element_type.default),
)
@pytest.mark.parametrize("destination", (torch.float16, torch.bfloat16))
@pytest.mark.parametrize(
    "source,expected",
    (
        (torch.int8, True),
        (torch.uint8, True),
        (torch.int16, False),
        (torch.int32, False),
        (torch.int64, False),
        (torch.bool, True),
        (torch.float32, True),
    ),
)
def test_full_dtype_range_not_sample_values(
    source: torch.dtype,
    destination: torch.dtype,
    target: OpOverload,
    expected: bool,
) -> None:
    assert _exact_integer_cast(_cast(source, destination, target)) is expected


@pytest.mark.parametrize("destination", (torch.float16, torch.bfloat16))
@pytest.mark.parametrize("kind", ("low", "high", "byte"))
def test_signed_fields_survive_integer_widening(
    kind: str, destination: torch.dtype
) -> None:
    if kind == "low":
        case = _graph(0, 4)
    elif kind == "high":
        case = _graph(4, 4, shift_only=True)
    else:
        case = _graph(0, 8, identity=True)
    case.value.kwargs = {"dtype": destination}
    case.value.meta["val"] = torch.empty((2, 8), dtype=destination)
    assert case.value.args[0].meta["val"].dtype is torch.int32
    assert _exact_integer_cast(case.value)


@pytest.mark.parametrize(
    "fault",
    (
        "wide_load",
        "wrong_sign_threshold",
        "extra_integer_arithmetic",
        "foreign_graph_operand",
        "missing_input_type",
        "missing_output_type",
        "inconsistent_output_type",
        "extra_cast_keyword",
    ),
)
def test_unproved_or_stale_field_declines(fault: str) -> None:
    case = _graph(0, 4)
    integer = case.value.args[0]
    assert isinstance(integer, Node)
    if fault == "wide_load":
        case.source.meta["val"] = torch.empty((2, 8), dtype=torch.int16)
        case.load.meta["val"] = torch.empty((2, 8), dtype=torch.int16)
    elif fault == "wrong_sign_threshold":
        condition = integer.args[0]
        assert isinstance(condition, Node)
        condition.args = (condition.args[0], 7)
    elif fault == "extra_integer_arithmetic":
        changed = case.graph.call_function(torch.ops.aten.add.Scalar, (integer, 1))
        changed.meta["val"] = torch.empty((2, 8), dtype=torch.int32)
        case.value.args = (changed,)
    elif fault == "foreign_graph_operand":
        case.value.args = (_graph(0, 4).value.args[0],)
    elif fault == "missing_input_type":
        integer.meta.clear()
    elif fault == "missing_output_type":
        case.value.meta.clear()
    elif fault == "inconsistent_output_type":
        case.value.meta["val"] = torch.empty((2, 8), dtype=torch.float16)
    elif fault == "extra_cast_keyword":
        case.value.kwargs = {"dtype": torch.bfloat16, "non_blocking": True}
    else:
        raise AssertionError(fault)
    # A copied semantic annotation cannot rescue an invalid current graph.
    case.value.meta["cute_signed_bitfield_bf16"] = {
        "signed": True,
        "bounds": (-8, 7),
    }
    assert not _exact_integer_cast(case.value)


def test_whole_graph_copy_reproves_current_field() -> None:
    case = _graph(0, 4)
    copied = Graph()
    values: dict[Node, Node] = {}
    for node in case.graph.nodes:
        values[node] = copied.node_copy(node, lambda item: values[item])
    value = values[case.value]
    value.meta["cute_signed_bitfield_bf16"] = {"old_load": case.load}
    assert value.graph is not case.graph
    assert _exact_integer_cast(value)


def test_floating_arithmetic_recipe_is_unchanged() -> None:
    cast = _cast(torch.float32, torch.bfloat16, torch.ops.aten._to_copy.default)
    source = cast.args[0]
    assert isinstance(source, Node)
    product = cast.graph.call_function(torch.ops.aten.mul.Scalar, (source, 0.25))
    product.meta["val"] = torch.empty((2, 8), dtype=torch.float32)
    cast.args = (product,)
    assert _exact_integer_cast(product)
    assert _exact_integer_cast(cast)


@helion.kernel(backend="cute", static_shapes=True, autotune_effort="none")
def _direct_cast_rhs(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
    m, k = a.shape
    n = b.shape[1]
    output = torch.empty((m, n), dtype=a.dtype, device=a.device)
    for row, column in hl.tile((m, n)):
        accumulator = hl.zeros([row, column], dtype=torch.float32)
        for inner in hl.tile(k):
            operand = b[inner, column].to(a.dtype)
            accumulator = torch.addmm(accumulator, a[row, inner], operand)
        output[row, column] = accumulator.to(a.dtype)
    return output


@helion.kernel(backend="cute", static_shapes=True, autotune_effort="none")
def _derived_cast_rhs(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
    m, k = a.shape
    n = b.shape[1]
    output = torch.empty((m, n), dtype=a.dtype, device=a.device)
    for row, column in hl.tile((m, n)):
        accumulator = hl.zeros([row, column], dtype=torch.float32)
        for inner in hl.tile(k):
            operand = (b[inner, column] + 1).to(a.dtype)
            accumulator = torch.addmm(accumulator, a[row, inner], operand)
        output[row, column] = accumulator.to(a.dtype)
    return output


@pytest.mark.parametrize("destination", (torch.float16, torch.bfloat16))
@pytest.mark.parametrize(
    "source,derived_expected",
    (
        (torch.int8, True),
        (torch.uint8, True),
        (torch.int16, False),
        (torch.int32, False),
    ),
)
@pytest.mark.parametrize("derived", (False, True))
@skipUnlessBackends(["cute"])
def test_actual_recipe_admission_uses_integer_precision(
    source: torch.dtype, destination: torch.dtype, derived_expected: bool, derived: bool
) -> None:
    # A bare cast of the loaded tile is rounded to the half format by the
    # original program too, so it is admitted at every integer width; derived
    # integer arithmetic still needs the proved-range check.
    expected = derived_expected if derived else True
    with (
        _cpu_target(),
        patch.object(
            CuteTcgen05Config, "per_cta_smem_capacity_bytes", return_value=232448
        ),
    ):
        kernel = helion.kernel(
            (_derived_cast_rhs if derived else _direct_cast_rhs).fn,
            backend="cute",
            static_shapes=True,
            autotune_effort="none",
            cute_materialize_transformed_operands=True,
        )
        args = (
            torch.empty((16, 32), dtype=destination),
            torch.empty((32, 16), dtype=source),
        )
        bound = kernel._bind_isolated(args)
        assert (bound.env.cute_fission_plan is not None) is expected

from __future__ import annotations

from typing import TYPE_CHECKING
from unittest.mock import patch

import pytest
import torch

import helion
from helion._compiler.cute.memory_ops import (
    _PERSISTENT_VEC_ALIGNMENT_SPECIALIZATION_KEY,
)
from helion._compiler.cute.memory_ops import _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY
from helion._compiler.cute.memory_ops import _persistent_vec_alignment_matrix_signature
from helion._testing import patch_cute_mma_support
from helion._testing import skipUnlessBackends
import helion.language as hl
from helion.language.scan_ops import _associative_scan
from helion.runtime.kernel import BoundKernel

if TYPE_CHECKING:
    from collections.abc import Iterator

pytestmark = skipUnlessBackends(["cute"])
CPU_DEVICE = torch.device("cpu")


@pytest.fixture(autouse=True)
def _cpu_only() -> Iterator[None]:
    with (
        patch_cute_mma_support(),
        patch("torch.cuda.is_available", return_value=False),
        patch("torch.cuda._lazy_init", side_effect=AssertionError("CUDA forbidden")),
    ):
        yield


def _pointwise(x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
    out = torch.empty_like(x)
    for tile in hl.tile(x.numel()):
        out[tile] = x[tile] + y[tile]
    return out


@pytest.mark.parametrize("static_shapes", [False, True])
def test_unrelated_grid_has_no_alias_specialization(static_shapes: bool) -> None:
    kernel = helion.kernel(_pointwise, backend="cute", static_shapes=static_shapes)
    x = torch.empty(64, device=CPU_DEVICE)
    y = torch.empty_like(x)
    bound = kernel.bind((x, y))
    # Every CuTe kernel specializes on vector-alignment facts; those depend on
    # pointer residues only, never on storage overlap.
    assert set(bound.env.runtime_input_specializations) == {
        _PERSISTENT_VEC_ALIGNMENT_SPECIALIZATION_KEY
    }
    assert [
        extractor.specialization_key
        for extractor in kernel._specialize_extra[bound._base_spec_key]
    ] == [_PERSISTENT_VEC_ALIGNMENT_SPECIALIZATION_KEY]
    # This pointwise kernel does not reorder stores to an existing input, so
    # input aliasing should not create a redundant compiled variant.
    assert kernel.bind((x, x.view_as(x))) is bound


def test_explicit_specialization_schema_is_not_extended_by_unused_alias_facts() -> None:
    @helion.kernel(backend="cute", static_shapes=False)
    def specialized(x: torch.Tensor, y: torch.Tensor) -> torch.Tensor:
        size = hl.specialize(y.size(0))
        out = torch.empty_like(x)
        for tile in hl.tile(x.numel()):
            out[tile] = x[tile] + size
        return out

    args = (torch.empty(32, device=CPU_DEVICE), torch.empty(64, device=CPU_DEVICE))
    bound = specialized.bind(args)
    assert _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY not in (
        bound.env.runtime_input_specializations
    )
    extractors = specialized._specialize_extra[bound._base_spec_key]
    assert tuple(fn(args) for fn in extractors) == (
        64,
        _persistent_vec_alignment_matrix_signature(args),
    )


def test_container_grid_dispatch_does_not_recompile_without_alias_consumer() -> None:
    @helion.kernel(
        backend="cute", static_shapes=True, config=helion.Config(block_sizes=[64])
    )
    def add_list(xs: list[torch.Tensor]) -> torch.Tensor:
        out = torch.empty_like(xs[0])
        for tile in hl.tile(xs[0].numel()):
            out[tile] = xs[0][tile] + xs[1][tile]
        return out

    x, y = torch.randn(64, device=CPU_DEVICE), torch.randn(64, device=CPU_DEVICE)
    with patch.object(
        BoundKernel, "compile_config", return_value=lambda xs: xs[0] + xs[1]
    ) as compile_config:
        out = add_list([x, y])
    # Alignment facts re-resolve the bound kernel during dispatch, but without
    # an alias consumer every lookup lands on the single compiled variant.
    assert compile_config.call_count == 1
    assert len(add_list._bound_kernels) == 1
    assert _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY not in (
        add_list.bind(([x, y],)).env.runtime_input_specializations
    )
    assert len(add_list._bound_kernels) == 1
    torch.testing.assert_close(out, x + y)


def _matmul_into(a: torch.Tensor, b: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
    for row, column in hl.tile([a.size(0), b.size(1)]):
        acc = hl.zeros([row, column], dtype=torch.float32)
        for reduction in hl.tile(a.size(1)):
            acc = torch.addmm(acc, a[row, reduction], b[reduction, column])
        out[row, column] = acc.to(out.dtype)
    return out


@pytest.mark.parametrize("static_shapes", [False, True])
def test_grid_contraction_registers_alias_facts(static_shapes: bool) -> None:
    kernel = helion.kernel(_matmul_into, backend="cute", static_shapes=static_shapes)
    a = torch.empty((64, 32), dtype=torch.float16, device=CPU_DEVICE)
    b = torch.empty((32, 48), dtype=torch.float16, device=CPU_DEVICE)
    out = torch.empty((64, 48), dtype=torch.float16, device=CPU_DEVICE)
    bound = kernel.bind((a, b, out))
    # Collective MMA schedules prove the epilogue store disjoint from operand
    # loads only through these facts, so an aliasing launch cannot reuse the
    # bound kernel compiled for disjoint storage.
    assert _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY in (
        bound.env.runtime_input_specializations
    )
    shared = torch.empty(out.numel(), dtype=torch.float16, device=CPU_DEVICE)
    overlapping = (shared[: a.numel()].view_as(a), b, shared.view_as(out))
    assert kernel.bind(overlapping) is not bound


def _scan_into(x: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
    for channel, row in hl.tile([x.size(1), x.size(0)], block_size=[1, 128]):
        out[row, channel] = hl.cumsum(x[row, channel], dim=0)
    return out


@pytest.mark.parametrize("static_shapes", [False, True])
def test_grid_writing_container_input_view_registers_alias_guard(
    static_shapes: bool,
) -> None:
    @helion.kernel(backend="cute", static_shapes=static_shapes)
    def write_view(xs: list[torch.Tensor]) -> torch.Tensor:
        out = xs[1].view_as(xs[0])
        for tile in hl.tile(xs[0].numel()):
            out[tile] = xs[0][tile] + 1
        return out

    x, y = torch.empty(64), torch.empty(64)
    bound = write_view.bind(([x, y],))
    assert _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY in (
        bound.env.runtime_input_specializations
    )
    assert write_view.bind(([x, x.view_as(x)],)) is not bound


@pytest.mark.parametrize("static_shapes", [False, True])
def test_scan_preserves_alias_specialization_and_shuffle_scan_codegen(
    static_shapes: bool,
) -> None:
    kernel = helion.kernel(_scan_into, backend="cute", static_shapes=static_shapes)
    x = torch.empty((128, 3), device=CPU_DEVICE)
    out = torch.empty_like(x)
    bound = kernel.bind((x, out))
    assert _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY in (
        bound.env.runtime_input_specializations
    )
    config = bound.config_spec.default_config()
    # The default config puts the 128 scanned rows on 128 threads, which the
    # CuTe backend lowers as a cross-warp shuffle scan (see cute/scan_ops.py).
    assert "cute.arch.shuffle_sync_up(" in bound.to_code(config)
    for alias in (x, x.view_as(x)):
        alias_bound = kernel.bind((x, alias))
        assert alias_bound is not bound
        assert "cute.arch.shuffle_sync_up(" in alias_bound.to_code(config)


def test_nested_scan_registers_alias_facts_before_codegen() -> None:
    @helion.kernel(backend="cute", static_shapes=True)
    def nested(x: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        for channel, row in hl.tile([x.size(1), x.size(0)], block_size=[1, 128]):
            if channel.begin == 0:
                out[row, channel] = hl.cumsum(x[row, channel], dim=0)
            else:
                out[row, channel] = x[row, channel]
        return out

    x = torch.empty((128, 3), device=CPU_DEVICE)
    bound = nested.bind((x, torch.empty_like(x)))
    assert _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY in (
        bound.env.runtime_input_specializations
    )
    assert bound.host_function is not None
    ir = bound.host_function.device_ir
    scan_graphs = [
        info.graph_id
        for info in ir.graphs
        if any(node.target is _associative_scan for node in info.graph.nodes)
    ]
    assert scan_graphs and not set(scan_graphs).intersection(ir.root_ids)
    # Registration is conservative; the branch-nested scan still lowers (as a
    # shuffle scan over the 128 row threads) once the alias facts are known.
    assert "cute.arch.shuffle_sync_up(" in bound.to_code(
        bound.config_spec.default_config()
    )


def test_reduction_specializations_are_unchanged() -> None:
    @helion.kernel(backend="cute", static_shapes=True)
    def reduce_into(x: torch.Tensor, out: torch.Tensor) -> torch.Tensor:
        for row in hl.tile(x.size(0)):
            out[row] = x[row, :].sum(-1)
        return out

    bound = reduce_into.bind(
        (
            torch.empty((3, 128), device=CPU_DEVICE),
            torch.empty(3, device=CPU_DEVICE),
        )
    )
    assert {
        _PERSISTENT_VEC_ALIGNMENT_SPECIALIZATION_KEY,
        _TENSOR_DISJOINT_MATRIX_SPECIALIZATION_KEY,
    }.issubset(bound.env.runtime_input_specializations)
